sumarUnAnioFechaCivilIso = (fechaIso: string): string => {
  const [year = 0, month = 1, day = 1] = fechaIso.split("-").map(Number)
  const fecha = DateTime.makeUnsafe({ year: year + 1, month, day })
  const partes = DateTime.toPartsUtc(fecha)
  const yyyy = String(partes.year).padStart(4, "0")
  const mm = String(partes.month).padStart(2, "0")
  const dd = String(partes.day).padStart(2, "0")

  return `${yyyy}-${mm}-${dd}`
}

crearImporteMonetario = (valor: Decimal.Value): ImporteMonetario =>
  new Decimal(valor)

// Constantes Decimal compartidas para evitar mezclar literales `number` en
// acumuladores monetarios y para expresar identidades aritmeticas de dominio.
export const IMPORTE_CERO = crearImporteMonetario(0)
export const IMPORTE_UNO = crearImporteMonetario(1)

export const centimosAEuros = (centimos: number): ImporteMonetario =>
  crearImporteMonetario(centimos).div(100)

